mkdir -p /tmp/nbtools /home/analyst/work/figures/analysis && cat > /tmp/nbtools/nb.py <<'EOF'
import sys, nbformat, re, subprocess
NB = "/home/analyst/work/analysis.ipynb"
def load():
    try: return nbformat.read(NB, as_version=4)
    except FileNotFoundError:
        nb = nbformat.v4.new_notebook(); nb.metadata["kernelspec"]={"name":"python3","display_name":"Python 3","language":"python"}; return nb
def add(path):
    nb = load()
    txt = open(path).read()
    parts = re.split(r"^# %%(.*)$", txt, flags=re.M)
    for hdr, body in zip(parts[1::2], parts[2::2]):
        body = body.strip("\n")
        if "[markdown]" in hdr: nb.cells.append(nbformat.v4.new_markdown_cell(body))
        else: nb.cells.append(nbformat.v4.new_code_cell(body))
    nbformat.write(nb, NB)
def run():
    r = subprocess.run(["jupyter","nbconvert","--to","notebook","--execute","--inplace","--ExecutePreprocessor.timeout=600",NB],capture_output=True,text=True,cwd="/home/analyst/work")
    if r.returncode: print(r.stderr[-3000:])
def show(start):
    nb = load()
    for i,c in enumerate(nb.cells):
        if i < start or c.cell_type!="code": continue
        print(f"--- cell {i} ---")
        for o in c.outputs:
            if o.output_type=="stream": print(o.text)
            elif o.output_type=="error": print("ERROR:", o.ename, o.evalue)
            elif "text/plain" in o.get("data",{}): print("[display]", o.data["text/plain"][:3000] if "image/png" not in o.data else "<image>")
if __name__=="__main__":
    cmd=sys.argv[1]
    if cmd=="add": add(sys.argv[2])
    elif cmd=="run": run()
    elif cmd=="show": show(int(sys.argv[2]))
    elif cmd=="n": print(len(load().cells))
EOF
